import pathlib,sys,os,numpy as np,pandas as pd,json,itertools
r=pathlib.Path(__file__).resolve().parents[1];os.chdir(r);sys.path.insert(0,'code')
ns={};exec(pathlib.Path('code/06_latent_class.py').read_text().split('tr = df[df.split')[0],ns);tr=ns['df'];tr=tr[tr.split=='train'];points=pd.read_csv('out/corrected_lca_points.csv');diags=json.load(open('out/lca_fit_diagnostics.json'));summary=[];patterns=[]
for fit in diags:
 survey,scale,group=fit['survey'],fit['scale'],fit['group'];d=tr if survey=='NHIS' else pd.read_csv('data/proc/nhanes_analytic.csv');mask=d.disab==0 if group=='No disability' else d.disab==1 if group=='Any disability' else d['d_'+group]==1;inds=ns['IND'][scale] if survey=='NHIS' else ['phq_pos','wg_dep','therapy'];t=d[mask].dropna(subset=inds);x=t[inds].to_numpy();w=t.wt_pooled.to_numpy();w=w/w.sum();p=np.array(fit['probabilities']);pi=float(points[(points.survey==survey)&(points.scale==scale)&(points.group==group)].latent_prev.iloc[0]);U=np.array(list(itertools.product([0,1],repeat=len(inds))));pred=(1-pi)*np.prod(np.where(U==1,p[0],1-p[0]),axis=1)+pi*np.prod(np.where(U==1,p[1],1-p[1]),axis=1);obs=np.array([w[(x==u).all(axis=1)].sum() for u in U]);tv=.5*np.abs(obs-pred).sum();summary.append(dict(survey=survey,scale=scale,group=group,total_variation=tv,max_pattern_residual=float(np.max(np.abs(obs-pred))),n_patterns=len(U),nominal_model_df=len(U)-1-(2*len(inds)+1),formal_goodness_of_fit_p='not computed'))
 for u,a,b in zip(U,obs,pred):patterns.append(dict(survey=survey,scale=scale,group=group,pattern=''.join(map(str,u)),observed=a,fitted=b))
pd.DataFrame(summary).to_csv('out/lca_pattern_fit_summary.csv',index=False);pd.DataFrame(patterns).to_csv('out/lca_pattern_fit.csv',index=False);print('LCA PATTERN CHECK COMPLETE')
